import { useState } from 'react';
import Button from '../components/Button';

const initialTasks = [
  { id: 1, label: 'Review DBMS notes', done: true },
  { id: 2, label: 'Practice OS scheduling problems', done: false },
  { id: 3, label: 'Read CN packet flow', done: false },
  { id: 4, label: 'Sketch software architecture diagram', done: false },
];

export default function TasksPage() {
  const [tasks, setTasks] = useState(initialTasks);

  const toggleTask = (id) => {
    setTasks(tasks.map((task) => (task.id === id ? { ...task, done: !task.done } : task)));
  };

  return (
    <div className="space-y-8">
      <div className="rounded-[2rem] border border-slate-800 bg-slate-950/90 p-8 shadow-2xl shadow-slate-950/30">
        <h2 className="text-3xl font-semibold text-white">Daily learning tasks</h2>
        <p className="mt-3 text-slate-400">Check off your study items and keep your schedule on track.</p>
        <div className="mt-8 space-y-4">
          {tasks.map((task) => (
            <button
              key={task.id}
              type="button"
              onClick={() => toggleTask(task.id)}
              className={`flex w-full items-center justify-between rounded-3xl border px-5 py-4 text-left transition ${
                task.done ? 'border-cyan-500/30 bg-cyan-500/10 text-cyan-200' : 'border-slate-800 bg-slate-900/90 text-slate-200 hover:border-cyan-500/30'
              }`}
            >
              <span>{task.label}</span>
              <span className="text-sm">{task.done ? 'Done' : 'Pending'}</span>
            </button>
          ))}
        </div>
        <div className="mt-6 text-right">
          <Button variant="secondary">Add new task</Button>
        </div>
      </div>
    </div>
  );
}
